const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometry for Mekele, Ethiopia (13.496, 39.476)
  const mekele = ee.Geometry.Point([39.476, 13.496]);
  const roi = mekele.buffer(20000); // 20km buffer

  // 2. Time periods (using available data up to 2025)
  const start1984 = '1983-01-01';
  const end1984 = '1985-12-31';
  const start2025 = '2023-01-01';
  const end2025 = '2025-07-31';

  // 3. Function to get Landsat imagery (Landsat 5 for 1984, Landsat 9 for 2025)
  function getLandsatCollection(startDate, endDate, sensor) {
    let collection;
    if (sensor === 'L5') {
      collection = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
        .filterBounds(roi)
        .filterDate(startDate, endDate)
        .filter(ee.Filter.lt('CLOUD_COVER', 30));
    } else if (sensor === 'L9') {
      collection = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2')
        .filterBounds(roi)
        .filterDate(startDate, endDate)
        .filter(ee.Filter.lt('CLOUD_COVER', 30));
    }
    return collection;
  }

  // 4. NDBI calculation function (Built-up Index: (SWIR1 - NIR)/(SWIR1 + NIR))
  function calculateNDBI(image) {
    // Landsat bands: B5 = NIR, B6 = SWIR1 for L5; B5 = NIR, B6 = SWIR1 for L9
    const ndbi = image.normalizedDifference(['SR_B6', 'SR_B5']).rename('NDBI');
    return image.addBands(ndbi);
  }

  // 5. Process 1984 data
  const col1984 = getLandsatCollection(start1984, end1984, 'L5');
  const count1984 = col1984.size().getInfo();
  console.log(`1984 Images: ${count1984}`);

  // 6. Process 2025 data
  const col2025 = getLandsatCollection(start2025, end2025, 'L9');
  const count2025 = col2025.size().getInfo();
  console.log(`2025 Images: ${count2025}`);

  // 7. Check for empty collections
  if (count1984 === 0 || count2025 === 0) {
    console.log('<answer>C1</answer>');
    return;
  }

  // 8. Calculate median composites and NDBI
  const median1984 = col1984.median();
  const ndbi1984 = calculateNDBI(median1984).select('NDBI');

  const median2025 = col2025.median();
  const ndbi2025 = calculateNDBI(median2025).select('NDBI');

  // 9. Threshold for built-up area (NDBI > 0 typically indicates built-up)
  const threshold = 0.1;
  const built1984 = ndbi1984.gt(threshold);
  const built2025 = ndbi2025.gt(threshold);

  // 10. Count pixels
  const stats1984 = built1984.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: roi,
    scale: 300,
    maxPixels: 1e9
  });

  const stats2025 = built2025.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: roi,
    scale: 300,
    maxPixels: 1e9
  });

  // 11. Validate pixel counts
  const countBuilt1984 = stats1984.get('NDBI').getInfo();
  const countBuilt2025 = stats2025.get('NDBI').getInfo();

  console.log(`1984 Built-up pixels: ${countBuilt1984}`);
  console.log(`2025 Built-up pixels: ${countBuilt2025}`);

  if (countBuilt1984 === null || countBuilt2025 === null ||
      isNaN(countBuilt1984) || isNaN(countBuilt2025)) {
    console.log('<answer>C3</answer>');
    return;
  }

  if (countBuilt1984 === 0 || countBuilt2025 === 0) {
    console.log('<answer>C2</answer>');
    return;
  }

  // 12. Compare urban area
  const increasePercent = ((countBuilt2025 - countBuilt1984) / countBuilt1984) * 100;
  console.log(`Urban area change: ${increasePercent.toFixed(1)}%`);

  // Threshold for significant increase (>10% growth)
  if (increasePercent > 10) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
